import json

def validate_token_header(header):
    '''
Memvalidasi header token untuk memastikan algoritma didukung.

Fungsi ini memeriksa apakah field 'alg' dalam header berisi 'HS256'.
    '''
    if isinstance(header, str):
        try:
            header_dict = json.loads(header)
        except json.JSONDecodeError:
            return False # Header is a malformed JSON string
    elif isinstance(header, dict):
        header_dict = header
