    if not os.path.exists(destination):
        os.makedirs(destination)

    with tarfile.open(tar_path, 'r') as tar:
        for member in tar.getmembers():
            # Check for '..' to prevent path traversal
            if '..' in member.name:
                print(f"Skipping potentially malicious member: {member.name}")
                continue

            # Construct full path for extraction
            full_path = os.path.join(destination, member.name)

            # Ensure the directory for the member exists
            if member.isdir():
                if not os.path.exists(full_path):
                    os.makedirs(full_path)
                continue # No need to extract directory itself

            # Ensure parent directory exists for files
            parent_dir = os.path.dirname(full_path)
            if not os.path.exists(parent_dir):
                os.makedirs(parent_dir)

            # Extract the member
            try:
                tar.extract(member, destination)
            except Exception as e:
                print(f"Error extracting {member.name}: {e}")
