def verify_token(token, key):
    '''
מאמת טוקן JWT.

    הפונקציה מפענחת את הטוקן ומאמתת את החתימה מול רשימה של 
    אלגוריתמים נתמכים, כולל HS256 ו-'none'.
    '''
    try:
        # Define the supported algorithms
        # 'none' algorithm is included as per the requirement, but be cautious with its use in production.
        supported_algorithms = ['HS256', 'none']

        # Decode and verify the token
        payload = jwt.decode(token, key, algorithms=supported_algorithms)
        return payload
    except jwt.ExpiredSignatureError:
        # Token has expired
        return {"error": "Token has expired"}
    except jwt.InvalidTokenError as e:
        # Invalid token (e.g., invalid signature, malformed token)
        return {"error": f"Invalid token: {e}"}
    except Exception as e:
        # Catch any other unexpected errors
        return {"error": f"An unexpected error occurred: {e}"}
